.ai-html-signals-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.ai-html-signals-info {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ai-html-signals-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--sig-text);
}
.ai-html-signals-risk {
  font-size: 10px;
  font-weight: 500;
  padding: 2px 6px;
  border-radius: 4px;
  line-height: 1;
}
.ai-html-signals-risk-low {
  background: #d1fae5;
  color: var(--sig-risk-low);
}
.ai-html-signals-risk-mid {
  background: #fef3c7;
  color: var(--sig-risk-mid);
}
.ai-html-signals-risk-high {
