  background: var(--sig-primary);
  color: #fff;
  cursor: pointer;
  line-height: 1;
}
.ai-html-signals-followed {
  background: transparent;
  color: var(--sig-primary);
}
.ai-html-signals-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.ai-html-signals-metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ai-html-signals-label {
  font-size: 11px;
  color: var(--sig-text-sec);
  line-height: 1.3;
}
.ai-html-signals-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--sig-text);
  line-height: 1.3;
}
.ai-html-signals-up {
  color: var(--sig-up);
}
.ai-html-signals-down {
