.promo-deposit-ladder {
  --promo-bg: #0f172a;
  --promo-surface: rgba(255,255,255,0.06);
  --promo-border: rgba(255,255,255,0.08);
  --promo-text: var(--home-primary-faint);
  --promo-muted: var(--home-primary);
  --promo-accent: var(--home-primary);
  --promo-accent-dim: var(--home-primary);
  --promo-success: var(--home-primary);
  --promo-success-dim: var(--home-primary-faint);
  --promo-warn: #f59e0b;
  --radius: 6px;
  display: flex;
  width: 100%;
  min-height: 180px;
  background: var(--promo-bg);
  border-radius: 8px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--promo-text);
}

.promo-deposit-ladder .promo-main {
  flex: 1;
  padding: 24px 28px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.promo-deposit-ladder .promo-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.promo-deposit-ladder .promo-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  background: var(--promo-success-dim);
  color: var(--promo-success);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--radius);
  text-transform: uppercase;
}

.promo-deposit-ladder .promo-period {
  font-size: 12px;
  color: var(--promo-muted);
  letter-spacing: 0.01em;
}

.promo-deposit-ladder .promo-title {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 6px 0;
  letter-spacing: -0.01em;
}

.promo-deposit-ladder .promo-sub {
  font-size: 13px;
  color: var(--promo-muted);
  line-height: 1.5;
  margin: 0 0 20px 0;
}

.promo-deposit-ladder .ladder-progress {
  margin-bottom: 16px;
}

.promo-deposit-ladder .ladder-track {
  position: relative;
  height: 4px;
  background: var(--promo-surface);
  border-radius: 2px;
  margin-bottom: 12px;
}

.promo-deposit-ladder .ladder-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: var(--promo-success);
  border-radius: 2px;
  transition: width 0.4s ease;
}

.promo-deposit-ladder .ladder-marks {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 0;
}

.promo-deposit-ladder .mark {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--promo-bg);
  border: 2px solid var(--promo-border);
  box-shadow: 0 0 0 2px var(--promo-bg);
  transition: all 0.3s ease;
}

.promo-deposit-ladder .mark.done {
  background: var(--promo-success);
  border-color: var(--promo-success);
}

.promo-deposit-ladder .mark.active {
  background: var(--promo-bg);
  border-color: var(--promo-accent);
  box-shadow: 0 0 0 2px var(--promo-bg), 0 0 0 4px var(--promo-accent-dim);
}

.promo-deposit-ladder .ladder-labels {
  display: flex;
  justify-content: space-between;
}

.promo-deposit-ladder .label {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 60px;
}

.promo-deposit-ladder .label-tier {
  font-size: 12px;
  font-weight: 600;
  color: var(--promo-muted);
}

.promo-deposit-ladder .label.active .label-tier {
  color: var(--promo-accent);
}

.promo-deposit-ladder .label-reward {
  font-size: 14px;
  font-weight: 700;
  color: var(--promo-text);
}

.promo-deposit-ladder .label.done .label-reward {
  color: var(--promo-success);
}

.promo-deposit-ladder .promo-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--promo-muted);
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--promo-border);
}

.promo-deposit-ladder .promo-dock {
  width: 280px;
  padding: 24px;
  background: var(--promo-surface);
  border-left: 1px solid var(--promo-border);
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex-shrink: 0;
}

.promo-deposit-ladder .dock-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--promo-border);
  margin-bottom: 4px;
}

.promo-deposit-ladder .status-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.promo-deposit-ladder .status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--promo-success);
}

.promo-deposit-ladder .status-dot.pulse {
  animation: promo-pulse 2s ease-in-out infinite;
}

@keyframes promo-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.promo-deposit-ladder .status-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--promo-success);
}

.promo-deposit-ladder .status-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--promo-text);
}

.promo-deposit-ladder .status-label {
  font-size: 11px;
  color: var(--promo-muted);
  margin-left: 4px;
}

.promo-deposit-ladder .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 16px;
  border-radius: var(--radius);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
  width: 100%;
}

.promo-deposit-ladder .btn-primary {
  background: var(--promo-accent);
  color: #fff;
}

.promo-deposit-ladder .btn-primary:hover {
  background: var(--home-primary);
}

.promo-deposit-ladder .btn-secondary {
  background: transparent;
  color: var(--promo-muted);
  border: 1px solid var(--promo-border);
}

.promo-deposit-ladder .btn-secondary:hover {
  color: var(--promo-text);
  border-color: var(--promo-muted);
}

.promo-deposit-ladder .dock-terms {
  font-size: 11px;
  color: var(--promo-muted);
  line-height: 1.6;
  margin-top: 4px;
}

@media (max-width: 720px) {
  .promo-deposit-ladder {
    flex-direction: column;
  }
  .promo-deposit-ladder .promo-dock {
    width: 100%;
    border-left: none;
    border-top: 1px solid var(--promo-border);
    padding: 20px;
  }
  .promo-deposit-ladder .promo-main {
    padding: 20px;
  }
  .promo-deposit-ladder .ladder-labels {
    gap: 16px;
  }
  .promo-deposit-ladder .label {
    min-width: 0;
    flex: 1;
  }
}

.ao-ticker-strip {
  --ao-bg: #ffffff;
  --ao-text-primary: var(--home-primary);
  --ao-text-secondary: #64748b;
  --ao-text-tertiary: var(--home-primary);
  --ao-border: var(--home-primary-faint);
  --ao-accent: var(--home-primary);
  --ao-accent-light: var(--home-primary);
  --ao-credit: var(--home-primary);
  --ao-credit-bg: #d1fae5;
  --ao-radius: 6px;
  --ao-gap: 16px;

  width: 100%;
  background: var(--ao-bg);
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.ao-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ao-gap);
}

.ao-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ao-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ao-accent);
  position: relative;
  flex-shrink: 0;
}

.ao-pulse::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid var(--ao-accent-light);
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(0.8); opacity: 1; }
  100% { transform: scale(1.6); opacity: 0; }
}

.ao-currency {
  font-size: 12px;
  font-weight: 600;
  color: var(--ao-accent);
  background: var(--ao-accent-light);
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.02em;
}

.ao-total-label {
  font-size: 13px;
  color: var(--ao-text-secondary);
  font-weight: 500;
}

.ao-header-right {
  min-width: 0;
  text-align: right;
}

.ao-total-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.02em;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}

.ao-divider {
  height: 1px;
  background: var(--ao-border);
  margin: 16px 0;
}

.ao-metrics {
  display: flex;
  align-items: stretch;
  gap: 0;
}

.ao-metric {
  flex: 1;
  min-width: 0;
  padding: 0 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ao-metric:first-child {
  padding-left: 0;
}

.ao-metric:last-child {
  padding-right: 0;
}

.ao-metric-sep {
  width: 1px;
  flex-shrink: 0;
  background: var(--ao-border);
  margin: 4px 0;
}

.ao-metric-top {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ao-metric-label {
  font-size: 12px;
  color: var(--ao-text-secondary);
  font-weight: 500;
  white-space: nowrap;
}

.ao-metric-value {
  font-size: 18px;
  font-weight: 600;
  color: var(--ao-text-primary);
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
}

.ao-metric-value.ao-credit {
  color: var(--ao-credit);
}

.ao-metric-bottom {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-height: 22px;
}

.ao-breakdown-tag {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  background: var(--home-primary-faint);
  padding: 2px 8px;
  border-radius: 4px;
  font-weight: 500;
  white-space: nowrap;
}

.ao-breakdown-count {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 500;
  margin-left: auto;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .ao-ticker-strip {
    padding: 16px;
  }

  .ao-header {
    flex-wrap: wrap;
    gap: 8px;
  }

  .ao-header-right {
    width: 100%;
    text-align: left;
  }

  .ao-total-value {
    font-size: 24px;
  }

  .ao-metrics {
    flex-direction: column;
    gap: 12px;
  }

  .ao-metric {
    padding: 0;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
  }

  .ao-metric-sep {
    display: none;
  }

  .ao-metric-top {
    flex-direction: row;
    align-items: baseline;
    gap: 8px;
  }

  .ao-metric-bottom {
    justify-content: flex-end;
    margin-left: auto;
  }

  .ao-breakdown-count {
    margin-left: 0;
  }
}

@media (max-width: 480px) {
  .ao-metric {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .ao-metric-top {
    width: 100%;
    justify-content: space-between;
  }

  .ao-metric-bottom {
    width: 100%;
    justify-content: flex-start;
  }
}

