  height: 100%;
  position: relative;
}

.ct-trend-placeholder::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 100%;
  background: var(--home-primary-faint);
}

.ct-trend-placeholder::after {
  content: '';
  position: absolute;
  bottom: 8px;
  left: 8px;
  right: 8px;
  height: 2px;
  background: var(--home-primary-soft);
  border-radius: 1px;
  opacity: 0.5;
}

