}

.wh-status-icon {
  font-size: 13px;
  color: var(--wh-blue);
  font-weight: 500;
  line-height: 1;
  flex-shrink: 0;
}

.wh-status-text {
  font-size: 12px;
  color: var(--wh-text-secondary);
  line-height: 1.5;
  flex: 1;
  min-width: 0;
}

@media (max-width: 720px) {
  .wh-conversion-anchor {
    padding: 16px;
    gap: 14px;
  }

  .wh-top {
    flex-direction: column;
    gap: 16px;
  }

  .wh-metrics {
    width: 100%;
    justify-content: flex-start;
  }

  .wh-metric {
    flex: 1;
    padding: 0 16px;
  }

  .wh-metric:first-child {
    padding-left: 0;
  }

  .wh-metric:last-child {
    padding-right: 0;
  }

  .wh-actions {
    width: 100%;
  }

  .wh-btn {
    flex: 1;
    text-align: center;
    padding: 10px 16px;
  }

  .wh-status-bar {
    flex-wrap: wrap;
    gap: 8px;
  }

