.ao-ticker-strip {
  --ao-bg: #ffffff;
  --ao-surface: var(--home-primary-faint);
  --ao-border: var(--home-primary-faint);
  --ao-text-primary: var(--home-primary);
  --ao-text-secondary: #64748b;
  --ao-text-tertiary: var(--home-primary);
  --ao-accent: var(--home-primary);
  --ao-accent-light: var(--home-primary);
  --ao-pulse: #22c55e;
  --ao-success: #16a34a;
  --ao-radius: 6px;

  width: 100%;
  background: var(--ao-bg);
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.ao-ticker-strip__header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.ao-ticker-strip__pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ao-pulse);
  position: relative;
  flex-shrink: 0;
}

.ao-ticker-strip__pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: var(--ao-pulse);
  opacity: 0.3;
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(1); opacity: 0.3; }
  100% { transform: scale(2.5); opacity: 0; }
}

.ao-ticker-strip__currency {
  font-size: 11px;
  font-weight: 600;
  color: var(--ao-accent);
  background: var(--ao-accent-light);
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.ao-ticker-strip__label {
  font-size: 13px;
  color: var(--ao-text-secondary);
  font-weight: 400;
}

.ao-ticker-strip__total {
  font-size: 22px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.02em;
  margin-left: auto;
}

.ao-ticker-strip__divider {
  height: 1px;
  background: var(--ao-border);
  margin-bottom: 14px;
}

.ao-ticker-strip__metrics {
  display: flex;
  align-items: stretch;
  gap: 0;
}

.ao-ticker-strip__metric {
  flex: 1;
  padding: 0 16px;
  min-width: 0;
}

.ao-ticker-strip__metric:first-child {
  padding-left: 0;
}

.ao-ticker-strip__metric:last-child {
  padding-right: 0;
}

.ao-ticker-strip__metric-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.ao-ticker-strip__metric-label {
  font-size: 12px;
  color: var(--ao-text-secondary);
  font-weight: 400;
  white-space: nowrap;
}

.ao-ticker-strip__metric-value {
  font-size: 15px;
  font-weight: 600;
  color: var(--ao-text-primary);
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.ao-ticker-strip__metric-detail {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.ao-ticker-strip__currency-tag,
  .ao-ticker-strip__account-type,
  .ao-ticker-strip__avail-tag {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 400;
}

.ao-ticker-strip__count {
  font-size: 11px;
  color: var(--ao-text-secondary);
  font-weight: 500;
  margin-left: auto;
}

.ao-ticker-strip__account-sep,
  .ao-ticker-strip__avail-sep {
  font-size: 11px;
  color: var(--ao-text-tertiary);
}

.ao-ticker-strip__metric-divider {
  width: 1px;
  background: var(--ao-border);
  flex-shrink: 0;
}

.ao-ticker-strip__footer-line {
  height: 1px;
  background: var(--ao-border);
  margin-top: 14px;
  margin-bottom: 8px;
}

.ao-ticker-strip__footer-hint {
  text-align: center;
}

.ao-ticker-strip__footer-hint span {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 400;
}

@media (max-width: 720px) {
  .ao-ticker-strip {
    padding: 16px;
  }

  .ao-ticker-strip__total {
    font-size: 18px;
  }

  .ao-ticker-strip__metrics {
    flex-direction: column;
    gap: 12px;
  }

  .ao-ticker-strip__metric {
    padding: 12px 14px;
    background: var(--ao-surface);
    border-radius: var(--ao-radius);
    border: 1px solid var(--ao-border);
  }

  .ao-ticker-strip__metric:first-child,
  .ao-ticker-strip__metric:last-child {
    padding: 12px 14px;
  }

  .ao-ticker-strip__metric-divider {
    display: none;
  }

  .ao-ticker-strip__metric-top {
    margin-bottom: 8px;
  }

  .ao-ticker-strip__footer-line {
    margin-top: 12px;
  }
}

.kyc-status-card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #ffffff;
  border: 1px solid var(--home-primary-faint);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.kyc-status-bar {
  height: 3px;
  flex-shrink: 0;
}

.kyc-status-bar.pending {
  background: #f59e0b;
}

.kyc-status-bar.approved {
  background: var(--home-primary);
}

.kyc-status-bar.rejected {
  background: #ef4444;
}

.kyc-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  gap: 12px;
}

.kyc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.kyc-title {
  font-size: 15px;
  font-weight: 600;
  color: #0f172a;
  line-height: 1.3;
  margin: 0;
}

.kyc-badge {
  font-size: 11px;
  font-weight: 500;
  padding: 2px 8px;
  border-radius: 4px;
  white-space: nowrap;
  flex-shrink: 0;
}

.kyc-badge:where(:not(.approved):not(.rejected)) {
  background: #fef3c7;
  color: #92400e;
}

.kyc-badge.approved {
  background: #d1fae5;
  color: #065f46;
}

.kyc-badge.rejected {
  background: #fee2e2;
  color: #991b1b;
}

.kyc-info {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
  min-height: 0;
}

.kyc-field {
