  margin-top: auto;
  padding-top: 4px;
}

.kyc-btn {
  font-size: 12px;
  font-weight: 500;
  padding: 7px 14px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  line-height: 1.3;
  transition: all 0.15s ease;
  flex: 1;
  text-align: center;
