.wh-conversion {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  background: #ffffff;
  border-radius: 8px;
  padding: 24px 28px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.wh-conversion__main {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
  flex: 1;
  min-height: 0;
  gap: 32px;
}

.wh-conversion__greeting {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 0 0 auto;
  max-width: 420px;
}

.wh-conversion__identity {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
}

.wh-conversion__name {
  font-size: 16px;
  font-weight: 600;
  color: #1a1a2e;
  line-height: 1.4;
}

.wh-conversion__status-tag {
  font-size: 11px;
  font-weight: 500;
  color: var(--home-primary);
  background: var(--home-primary-faint);
  padding: 2px 10px;
  border-radius: 4px;
  line-height: 1.5;
}

.wh-conversion__greeting-text {
  font-size: 22px;
  font-weight: 600;
  color: #1a1a2e;
  line-height: 1.35;
  margin: 0;
  padding: 0;
}

.wh-conversion__mainline {
  font-size: 13px;
  color: #6b7280;
  line-height: 1.5;
  margin: 0;
  padding: 0;
}

.wh-conversion__metrics {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0;
  flex: 0 0 auto;
}

.wh-conversion__metric {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 0 20px;
}

.wh-conversion__metric:first-child {
  padding-left: 0;
}

.wh-conversion__metric:last-child {
  padding-right: 0;
}

.wh-conversion__metric-divider {
  width: 1px;
  height: 32px;
  background: #e5e7eb;
  flex-shrink: 0;
}

.wh-conversion__metric-label {
  font-size: 12px;
  color: #9ca3af;
  line-height: 1.4;
  font-weight: 400;
}

.wh-conversion__metric-value {
  font-size: 18px;
  font-weight: 600;
  color: #1a1a2e;
  line-height: 1.3;
}

.wh-conversion__metric-value--secondary {
  color: #4b5563;
}

.wh-conversion__actions {
  display: flex;
  flex-direction: row;
  gap: 10px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid #f3f4f6;
}

.wh-conversion__btn {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 20px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  line-height: 1.5;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
}

.wh-conversion__btn--primary {
  background: var(--home-primary);
  color: #ffffff;
}

.wh-conversion__btn--primary:var(--home-primary);
}

.wh-conversion__btn--secondary {
  background: #f8f9fa;
  color: var(--home-primary-strong);
  border: 1px solid #e5e7eb;
}

.wh-conversion__btn--secondary:hover {
  background: #f3f4f6;
}

@media (max-width: 720px) {
  .wh-conversion {
    padding: 20px;
  }

  .wh-conversion__main {
    flex-direction: column;
    gap: 20px;
  }

  .wh-conversion__greeting {
    max-width: none;
  }

  .wh-conversion__metrics {
    width: 100%;
    justify-content: flex-start;
  }

  .wh-conversion__metric {
    flex: 1;
    padding: 0 12px;
  }

  .wh-conversion__metric:first-child {
    padding-left: 0;
  }

  .wh-conversion__metric:last-child {
    padding-right: 0;
  }

  .wh-conversion__metric-divider {
    height: 28px;
  }

  .wh-conversion__metric-value {
    font-size: 16px;
  }

  .wh-conversion__actions {
    margin-top: 14px;
    padding-top: 14px;
  }

  .wh-conversion__btn {
    flex: 1;
    padding: 9px 16px;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .wh-conversion__metrics {
    flex-wrap: wrap;
    gap: 12px 0;
  }

  .wh-conversion__metric {
    flex: 1 1 45%;
    padding: 0;
  }

  .wh-conversion__metric-divider {
    display: none;
  }

  .wh-conversion__metric:nth-child(3) {
    flex-basis: 100%;
  }

  .wh-conversion__actions {
    flex-direction: column;
    gap: 8px;
  }

  .wh-conversion__btn {
    width: 100%;
  }
}

.ao-ticker-strip {
  --ao-text-primary: var(--home-primary);
  --ao-text-secondary: #5a6a7a;
  --ao-text-tertiary: #8a94a0;
  --ao-border: var(--home-primary-faint);
  --ao-surface: var(--home-primary-faint);
  --ao-accent: var(--home-primary);
  --ao-accent-light: var(--home-primary);
  --ao-credit: var(--home-primary);
  --ao-credit-light: var(--home-primary-faint);
  --ao-success: var(--home-primary);
  --ao-radius: 6px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', sans-serif;
  background: #fff;
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  width: 100%;
  box-sizing: border-box;
}

.ao-header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.ao-pulse-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ao-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ao-success);
  position: relative;
  flex-shrink: 0;
}

.ao-pulse::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: var(--ao-success);
  opacity: 0.25;
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(1); opacity: 0.25; }
  100% { transform: scale(2.2); opacity: 0; }
}

.ao-currency {
  font-size: 11px;
  font-weight: 600;
  color: var(--ao-text-tertiary);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.ao-total-group {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.ao-total-label {
  font-size: 13px;
  color: var(--ao-text-secondary);
  font-weight: 500;
}

.ao-total-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.3px;
}

.ao-account-badge {
  margin-left: auto;
  font-size: 11px;
  color: var(--ao-text-tertiary);
  background: var(--ao-surface);
  padding: 3px 10px;
  border-radius: 4px;
  font-weight: 500;
}

.ao-divider {
  height: 1px;
  background: var(--ao-border);
  margin: 14px 0;
}

.ao-metrics {
  display: flex;
  align-items: stretch;
  gap: 0;
}

.ao-metric {
  flex: 1;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 0 16px;
  min-width: 0;
}

.ao-metric:first-child {
  padding-left: 0;
}

.ao-metric:last-child {
  padding-right: 0;
}

.ao-metric-icon {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ao-accent-light);
  border-radius: var(--ao-radius);
  font-size: 14px;
  flex-shrink: 0;
  margin-top: 2px;
}

.ao-credit-icon {
  background: var(--ao-credit-light);
  color: var(--ao-credit);
  font-size: 13px;
}

.ao-metric-body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ao-metric-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.2px;
  line-height: 1.3;
}

.ao-metric-label {
  font-size: 12px;
  color: var(--ao-text-secondary);
  font-weight: 500;
}

.ao-metric-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.ao-meta-tag {
  font-size: 10px;
  color: var(--ao-text-tertiary);
  background: var(--ao-surface);
  padding: 2px 7px;
  border-radius: 3px;
  font-weight: 500;
  white-space: nowrap;
}

.ao-tag-muted {
  color: var(--home-primary);
  background: var(--ao-credit-light);
}

.ao-meta-count {
  font-size: 10px;
  color: var(--ao-text-tertiary);
  font-weight: 500;
}

.ao-meta-hint {
  font-size: 10px;
  color: var(--ao-text-tertiary);
  font-style: italic;
}

.ao-metric-sep {
  width: 1px;
  background: var(--ao-border);
  flex-shrink: 0;
  margin: 4px 0;
}

.ao-footer {
  display: flex;
  align-items: center;
  justify-content: center;
}

.ao-hint {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 500;
}

@media (max-width: 720px) {
  .ao-ticker-strip {
    padding: 16px;
  }

  .ao-header {
    gap: 8px;
  }

  .ao-total-value {
    font-size: 20px;
  }

  .ao-account-badge {
    margin-left: 0;
  }

  .ao-metrics {
    flex-direction: column;
    gap: 12px;
  }

  .ao-metric {
    padding: 0;
    flex-direction: row;
    align-items: flex-start;
  }

  .ao-metric-sep {
    display: none;
  }

  .ao-divider {
    margin: 12px 0;
  }
