  color: var(--ct-text-tertiary);
  font-size: 12px;
}

.ct-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.ct-card {
  border: 1px solid var(--ct-border);
  border-radius: 6px;
  padding: 16px;
  background: var(--ct-bg);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
