  flex-direction: column;
  gap: 3px;
}
.ct-metric--primary .ct-metric-value {
  font-size: 18px;
  font-weight: 700;
}
.ct-metric-label {
  font-size: 11px;
  color: var(--ct-text-tertiary);
  line-height: 1.3;
}
.ct-metric-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--ct-text);
  line-height: 1.3;
}
.ct-metric-value--up { color: var(--ct-success); }

.ct-drawdown {
