  gap: 6px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--ct-border);
}
.ct-drawdown-label {
  font-size: 11px;
  color: var(--ct-text-tertiary);
}
.ct-drawdown-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--ct-text-secondary);
}

.ct-chart-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  margin-bottom: 12px;
}
.ct-chart-tabs {
  display: flex;
  gap: 2px;
  margin-bottom: 8px;
}
.ct-chart-tab {
  font-size: 11px;
  font-weight: 500;
  color: var(--ct-text-tertiary);
