  color: var(--ct-primary);
  background: var(--home-primary-faint);
}
.ct-chart-area {
  flex: 1;
  min-height: 48px;
  position: relative;
}
.ct-chart-area svg {
  width: 100%;
  height: 100%;
  display: block;
}

.ct-dock {
  margin-top: auto;
  padding-top: 4px;
}
.ct-btn {
  width: 100%;
  padding: 8px 0;
  font-size: 13px;
  font-weight: 500;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.15s;
  line-height: 1;
  border: none;
}
.ct-btn--primary {
  background: var(--ct-primary);
  color: #fff;
}
.ct-btn--primary:hover { background: var(--ct-primary-hover); }
.ct-btn--ghost {
  background: transparent;
  color: var(--ct-text-secondary);
