.ob-next-hero {
  --ob-bg: #ffffff;
  --ob-border: var(--home-primary-faint);
  --ob-text: #1a1d2b;
  --ob-text-secondary: #6b7280;
  --ob-text-muted: #9ca3af;
  --ob-done: var(--home-primary);
  --ob-done-bg: var(--home-primary-faint);
  --ob-current: var(--home-primary);
  --ob-current-bg: var(--home-primary-faint);
  --ob-pending: #d1d5db;
  --ob-pending-bg: var(--home-primary-faint);
  --ob-radius: 6px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--ob-bg);
  border: 1px solid var(--ob-border);
  border-radius: var(--ob-radius);
  padding: 24px;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
}

.ob-next-hero__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  flex-shrink: 0;
}

.ob-next-hero__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ob-text);
  margin: 0;
  line-height: 1.4;
}

.ob-next-hero__counter {
  font-size: 13px;
  font-weight: 500;
  color: var(--ob-text-secondary);
  background: #f3f4f6;
  padding: 3px 10px;
  border-radius: 4px;
}

.ob-next-hero__body {
  display: flex;
  gap: 28px;
  flex: 1;
  min-height: 0;
}

.ob-next-hero__steps {
  display: flex;
  flex-direction: column;
  gap: 0;
  flex-shrink: 0;
  width: 140px;
}

.ob-step {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  position: relative;
  padding-bottom: 16px;
}

.ob-step:last-child {
  padding-bottom: 0;
}

.ob-step__dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  flex-shrink: 0;
  z-index: 2;
}

.ob-step--done .ob-step__dot {
  background: var(--ob-done);
  color: #fff;
}

.ob-step--current .ob-step__dot {
  background: var(--ob-current);
  color: #fff;
}

.ob-step--pending .ob-step__dot {
  background: var(--ob-pending-bg);
  color: var(--ob-text-muted);
  border: 1.5px solid var(--ob-pending);
}

.ob-step__dot svg {
  width: 12px;
  height: 12px;
}

.ob-step__line {
  position: absolute;
  left: 10.5px;
  top: 22px;
  width: 1.5px;
  height: calc(100% - 6px);
  background: var(--ob-done);
  z-index: 1;
}

.ob-step__line--pending {
  background: var(--ob-pending);
}

.ob-step:last-child .ob-step__line {
  display: none;
}

.ob-step__content {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 2px;
}

.ob-step__label {
  font-size: 12px;
  font-weight: 500;
  color: var(--ob-text);
  line-height: 1.4;
}

.ob-step__status {
  font-size: 11px;
  font-weight: 500;
  line-height: 1.4;
}

.ob-step--done .ob-step__status {
  color: var(--ob-done);
}

.ob-step__status--current {
  color: var(--ob-current);
}

.ob-step__status--pending {
  color: var(--ob-text-muted);
}

.ob-next-hero__action {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-left: 1px solid var(--ob-border);
  padding-left: 28px;
}

.ob-next-hero__action-head {
  margin-bottom: 16px;
}

.ob-next-hero__badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 500;
  color: var(--ob-current);
  background: var(--ob-current-bg);
  padding: 3px 10px;
  border-radius: 4px;
  margin-bottom: 8px;
}

.ob-next-hero__lead {
  font-size: 14px;
  font-weight: 500;
  color: var(--ob-text);
  margin: 0;
  line-height: 1.5;
}

.ob-next-hero__config {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.ob-config-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.ob-config-row__key {
  font-size: 12px;
  color: var(--ob-text-secondary);
  line-height: 1.4;
}

.ob-config-row__val {
  font-size: 12px;
  font-weight: 500;
  color: var(--ob-text);
  line-height: 1.4;
}

.ob-next-hero__dock {
  display: flex;
  gap: 10px;
  margin-top: auto;
  flex-wrap: wrap;
}

.ob-btn {
  font-size: 12px;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--ob-radius);
  border: none;
  cursor: pointer;
  line-height: 1.5;
  transition: background 0.15s ease;
  white-space: nowrap;
}

.ob-btn--primary {
  background: var(--ob-current);
  color: #fff;
}

.ob-btn--primary:var(--home-primary);
}

.ob-btn--secondary {
  background: #f3f4f6;
  color: var(--ob-text);
  border: 1px solid var(--ob-border);
}

.ob-btn--secondary:hover {
  background: #e5e7eb;
}

@media (max-width: 720px) {
  .ob-next-hero {
    padding: 20px;
  }

  .ob-next-hero__body {
    flex-direction: column;
    gap: 20px;
  }

  .ob-next-hero__steps {
    flex-direction: row;
    width: 100%;
    gap: 0;
  }

  .ob-step {
    flex: 1;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding-bottom: 0;
    padding-right: 8px;
  }

  .ob-step:last-child {
    padding-right: 0;
  }

  .ob-step__line {
    display: none;
  }

  .ob-step__content {
    padding-top: 6px;
  }

  .ob-next-hero__action {
    border-left: none;
    padding-left: 0;
    border-top: 1px solid var(--ob-border);
    padding-top: 20px;
  }

  .ob-next-hero__dock {
    flex-direction: column;
  }

  .ob-btn {
    width: 100%;
    text-align: center;
  }
}

.fcrm-ref-strip {
