    padding: 16px;
  }

  .fcrm-ref-strip__main {
    flex-direction: column;
    gap: 16px;
  }

  .fcrm-ref-strip__link-col {
    flex: 1 1 auto;
  }

  .fcrm-ref-strip__metrics {
    flex: 1 1 auto;
    flex-direction: row;
    padding: 12px;
  }

  .fcrm-ref-strip__metric-num {
    font-size: 18px;
  }
}

@media (max-width: 400px) {
  .fcrm-ref-strip__value-row {
    flex-wrap: wrap;
  }

  .fcrm-ref-strip__url {
    max-width: 100%;
  }

  .fcrm-ref-strip__metrics {
