    order: 1;
  }

  .fcrm-ref-strip__metric-rate,
  .fcrm-ref-strip__metric-delta {
    order: 3;
    margin-left: auto;
  }
}

.ta-brick {
  --ta-bg: #ffffff;
  --ta-surface: var(--home-primary-faint);
  --ta-border: var(--home-primary-faint);
  --ta-text: #0f172a;
  --ta-text-secondary: #64748b;
  --ta-text-tertiary: var(--home-primary);
  --ta-live: #dc2626;
  --ta-live-bg: #fef2f2;
  --ta-demo: var(--home-primary);
  --ta-demo-bg: var(--home-primary-faint);
  --ta-ok: #16a34a;
  --ta-warn: #d97706;
  --ta-blue: var(--home-primary);
  --ta-blue-hover: var(--home-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--ta-bg);
  border-radius: 6px;
  padding: 24px;
  height: 100%;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.ta-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  flex-shrink: 0;
}

.ta-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--ta-text);
  margin: 0;
  line-height: 1.4;
}

.ta-tabs {
  display: flex;
  gap: 4px;
  background: var(--ta-surface);
  border-radius: 6px;
  padding: 3px;
}

.ta-tab {
  font-size: 12px;
  font-weight: 500;
  color: var(--ta-text-secondary);
  background: transparent;
  border: none;
  border-radius: 4px;
  padding: 5px 14px;
  cursor: pointer;
  line-height: 1.4;
  transition: all 0.15s ease;
}

.ta-tab:hover {
  color: var(--ta-text);
}

.ta-tab--active {
  background: var(--ta-bg);
  color: var(--ta-text);
  box-shadow: 0 1px 2px rgba(0,0,0,0.06);
}

.ta-group {
  margin-bottom: 16px;
  flex-shrink: 0;
}

.ta-group:last-of-type {
  margin-bottom: 0;
}

.ta-group-hd {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
  padding: 0 2px;
}

.ta-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 4px;
  line-height: 1.4;
}

.ta-badge--live {
  color: var(--ta-live);
  background: var(--ta-live-bg);
}

.ta-badge--demo {
  color: var(--ta-demo);
  background: var(--ta-demo-bg);
}

.ta-count {
  font-size: 12px;
  color: var(--ta-text-tertiary);
  font-weight: 400;
}

.ta-rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ta-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 16px;
  background: var(--ta-surface);
  border-radius: 6px;
  border: 1px solid var(--ta-border);
  transition: border-color 0.15s ease;
}

.ta-row:hover {
  border-color: var(--home-primary-soft);
}

.ta-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ta-cell--id {
  min-width: 170px;
  flex-shrink: 0;
}

.ta-env {
  font-size: 11px;
  color: var(--ta-text-tertiary);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ta-acct {
  font-size: 14px;
  font-weight: 600;
  color: var(--ta-text);
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
}

.ta-cell--metrics {
  flex: 1;
  display: flex;
  flex-direction: row;
  gap: 20px;
  min-width: 0;
}

.ta-metric {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.ta-metric-label {
  font-size: 11px;
  color: var(--ta-text-tertiary);
  line-height: 1.4;
}

.ta-metric-val {
  font-size: 13px;
  font-weight: 600;
  color: var(--ta-text);
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ta-cell--spec {
  min-width: 90px;
  flex-shrink: 0;
  align-items: flex-end;
  text-align: right;
}

.ta-spec {
  font-size: 12px;
  color: var(--ta-text-secondary);
  line-height: 1.4;
  white-space: nowrap;
}

.ta-leverage {
  font-size: 11px;
  color: var(--ta-text-tertiary);
  line-height: 1.4;
}

.ta-cell--status {
  min-width: 80px;
  flex-shrink: 0;
  align-items: flex-end;
}

.ta-status-bar {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  width: 100%;
}

.ta-status-track {
  width: 56px;
  height: 4px;
  background: var(--home-primary-faint);
  border-radius: 2px;
  overflow: hidden;
}

.ta-status-fill {
  height: 100%;
  background: var(--ta-ok);
  border-radius: 2px;
  transition: width 0.3s ease;
}

.ta-status-fill--warn {
  background: var(--ta-warn);
}

.ta-status-text {
  font-size: 12px;
  font-weight: 600;
  color: var(--ta-ok);
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
}

.ta-status-text--warn {
  color: var(--ta-warn);
}

.ta-actions {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 16px;
  flex-shrink: 0;
}

.ta-btn {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 18px;
  border-radius: 6px;
  cursor: pointer;
  line-height: 1.4;
  transition: all 0.15s ease;
  flex: 1;
  text-align: center;
}

.ta-btn--secondary {
  color: var(--ta-text-secondary);
  background: var(--ta-surface);
  border: 1px solid var(--ta-border);
}

.ta-btn--secondary:hover {
  color: var(--ta-text);
  background: var(--home-primary-faint);
  border-color: var(--home-primary-soft);
}

@media (max-width: 720px) {
  .ta-brick {
    padding: 16px;
  }

  .ta-head {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 16px;
  }

  .ta-row {
    flex-wrap: wrap;
    gap: 12px;
    padding: 12px;
  }

  .ta-cell--id {
    min-width: auto;
    flex: 1 1 100%;
    flex-direction: row;
    align-items: baseline;
    gap: 8px;
  }

  .ta-env {
    order: 2;
  }

  .ta-acct {
    order: 1;
  }

  .ta-cell--metrics {
    flex: 1 1 calc(100% - 100px);
    gap: 16px;
  }

  .ta-cell--spec {
