.ao-ticker-strip {
  --ao-bg: #ffffff;
  --ao-surface: var(--home-primary-faint);
  --ao-border: var(--home-primary-faint);
  --ao-text-primary: var(--home-primary);
  --ao-text-secondary: var(--home-primary);
  --ao-text-tertiary: var(--home-primary);
  --ao-accent: var(--home-primary);
  --ao-accent-hover: var(--home-primary);
  --ao-accent-light: var(--home-primary);
  --ao-success: var(--home-primary);
  --ao-success-bg: #d1fae5;
  --ao-pulse: #22c55e;
  --ao-radius: 6px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--ao-bg);
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 0;
  box-sizing: border-box;
}

.ao-ticker-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.ao-ticker-title {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ao-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ao-pulse);
  position: relative;
  flex-shrink: 0;
}

.ao-pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 1.5px solid var(--ao-pulse);
  opacity: 0.4;
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(1); opacity: 0.4; }
  100% { transform: scale(2.2); opacity: 0; }
}

.ao-currency-tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--ao-accent);
  background: var(--ao-accent-light);
  padding: 2px 8px;
