  flex-direction: column;
  gap: 6px;
}

.ao-metric-top {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ao-metric-icon {
  font-size: 14px;
  line-height: 1;
  flex-shrink: 0;
}

.ao-metric-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--ao-text-secondary);
  letter-spacing: 0.01em;
}

.ao-metric-value {
  font-size: 18px;
  font-weight: 600;
  color: var(--ao-text-primary);
  line-height: 1.3;
  font-variant-numeric: tabular-nums;
}

.ao-metric-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  min-height: 20px;
}

.ao-meta-tag {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 500;
}

.ao-meta-divider {
  font-size: 11px;
  color: var(--ao-text-tertiary);
