}

.ao-status-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  line-height: 1.4;
}

.ao-status-active {
  color: var(--ao-success);
  background: var(--ao-success-bg);
}

.ao-meta-hint {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 400;
}

.ao-metric-connector {
  width: 1px;
  background: var(--ao-border);
  flex-shrink: 0;
  margin: 12px 0;
