}

.ao-btn-secondary:hover {
  background: var(--home-primary-faint);
  border-color: var(--home-primary-soft);
}

@media (max-width: 720px) {
  .ao-ticker-strip {
    padding: 16px;
    gap: 14px;
  }

  .ao-total-value {
    font-size: 24px;
  }

  .ao-metrics-band {
    flex-direction: column;
  }

  .ao-metric-cell {
    padding: 14px 16px;
