  }

  .ao-metric-top {
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    min-width: 80px;
  }

  .ao-metric-value {
    font-size: 16px;
    min-width: 100px;
  }

  .ao-metric-meta {
    flex: 1;
    justify-content: flex-end;
    min-width: 120px;
  }

  .ao-metric-connector {
    width: auto;
    height: 1px;
    margin: 0 16px;
  }

  .ao-action-dock {
    gap: 8px;
  }

  .ao-btn {
    padding: 12px 16px;
    font-size: 14px;
  }
