  --qa-text-secondary: #6b7a8f;
  --qa-blue: var(--home-primary);
  --qa-blue-hover: var(--home-primary);
  --qa-blue-light: var(--home-primary-faint);
  --qa-blue-border: var(--home-primary-soft);
  --qa-radius: 6px;
  --qa-gap: 12px;

  width: 100%;
  background: var(--qa-bg);
  border: 1px solid var(--qa-border);
  border-radius: var(--qa-radius);
  padding: 20px 24px 24px;
  box-sizing: border-box;
}

.qa-dock__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.qa-dock__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--qa-text);
  line-height: 1.3;
  margin: 0;
}

.qa-dock__primary {
  font-size: 13px;
  font-weight: 600;
  color: #ffffff;
  background: var(--qa-blue);
  border: none;
  border-radius: var(--qa-radius);
