  border-color: var(--qa-blue-border);
}

.qa-dock__cell--fund .qa-dock__icon {
  color: var(--qa-blue);
}

.qa-dock__cell--fund .qa-dock__label {
  color: var(--qa-blue);
  font-weight: 600;
}

.qa-dock__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  color: var(--qa-text-secondary);
  flex-shrink: 0;
}

.qa-dock__icon svg {
