  --kyc-done: var(--home-primary);
  --kyc-current: #f59e0b;
  --kyc-pending: #d1d5db;
  --kyc-text: #1f2937;
  --kyc-text-secondary: #6b7280;
  --kyc-border: #e5e7eb;
  --kyc-bg: #ffffff;
