  border-radius: 6px;
  padding: 20px;
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.ch-kyc-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ch-kyc-ring {
  position: relative;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
}

