  fill: none;
  stroke: var(--kyc-current);
  stroke-width: 3;
  stroke-linecap: round;
  transition: stroke-dasharray 0.3s ease;
}

.ch-kyc-ring-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  color: var(--kyc-text);
}

.ch-kyc-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.ch-kyc-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--kyc-text);
  line-height: 1.3;
}

.ch-kyc-status-tag {
  display: inline-flex;
  align-self: flex-start;
  font-size: 11px;
  font-weight: 500;
  padding: 2px 8px;
  border-radius: 4px;
  line-height: 1.4;
}

.ch-kyc-status-tag[data-status="in-progress"] {
  background: #fef3c7;
  color: #92400e;
}

.ch-kyc-status-tag[data-status="done"] {
  background: #d1fae5;
  color: #065f46;
}

.ch-kyc-status-tag[data-status="pending"] {
  background: #f3f4f6;
  color: #6b7280;
}

.ch-kyc-steps {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding-left: 4px;
}

.ch-kyc-step {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  position: relative;
  padding-bottom: 14px;
}

.ch-kyc-step:last-child {
  padding-bottom: 0;
}

.ch-kyc-step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 5px;
  flex-shrink: 0;
  position: relative;
  z-index: 2;
}

.ch-kyc-step[data-state="done"] .ch-kyc-step-dot {
  background: var(--kyc-done);
}

.ch-kyc-step[data-state="current"] .ch-kyc-step-dot {
  background: var(--kyc-current);
  box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.15);
}

.ch-kyc-step[data-state="pending"] .ch-kyc-step-dot {
  background: var(--kyc-pending);
}

.ch-kyc-step-line {
  position: absolute;
  left: 3px;
  top: 13px;
  width: 2px;
  height: calc(100% - 6px);
  background: var(--kyc-pending);
  z-index: 1;
}

.ch-kyc-step[data-state="done"] .ch-kyc-step-line {
  background: var(--kyc-done);
}

.ch-kyc-step:last-child .ch-kyc-step-line {
  display: none;
}

.ch-kyc-step-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.ch-kyc-step-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--kyc-text);
  line-height: 1.4;
}

.ch-kyc-step-meta {
  font-size: 11px;
  color: var(--kyc-text-secondary);
  line-height: 1.4;
}

.ch-kyc-step[data-state="done"] .ch-kyc-step-meta {
  color: var(--kyc-done);
}

.ch-kyc-step[data-state="current"] .ch-kyc-step-meta {
  color: var(--kyc-current);
  font-weight: 500;
}

.ch-kyc-action {
  margin-top: 4px;
}

.ch-kyc-btn {
  width: 100%;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 500;
  color: #ffffff;
  background: var(--kyc-btn);
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s ease;
  line-height: 1.4;
}

.ch-kyc-btn:hover {
  background: var(--kyc-btn-hover);
}

@media (max-width: 480px) {
  .ch-kyc-compact {
    padding: 16px;
    gap: 14px;
  }

  .ch-kyc-title {
    font-size: 14px;
  }

  .ch-kyc-btn {
    padding: 10px 16px;
  }
}

.ap-prochart {
  --ap-c-bg: #ffffff;
  --ap-c-surface: var(--home-primary-faint);
  --ap-c-border: var(--home-primary-faint);
  --ap-c-text: #0f172a;
  --ap-c-text-secondary: #64748b;
  --ap-c-text-tertiary: var(--home-primary);
  --ap-c-primary: var(--home-primary);
  --ap-c-primary-hover: var(--home-primary);
  --ap-c-up: #16a34a;
  --ap-c-down: #dc2626;
  --ap-c-live: #16a34a;
  --ap-c-radius: 6px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--ap-c-bg);
  border: 1px solid var(--ap-c-border);
  border-radius: var(--ap-c-radius);
  width: 100%;
  min-height: 100%;
  box-sizing: border-box;
}

.ap-prochart__main {
  display: flex;
  gap: 0;
  min-height: 100%;
}

.ap-prochart__left {
  flex: 0 0 42%;
  max-width: 380px;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-right: 1px solid var(--ap-c-border);
}

.ap-prochart__right {
  flex: 1 1 auto;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Account Context */
.ap-prochart__account {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.ap-prochart__account-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.ap-prochart__badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.ap-prochart__badge--live {
  background: #dcfce7;
  color: var(--ap-c-up);
}

.ap-prochart__platform {
  font-size: 12px;
  font-weight: 500;
  color: var(--ap-c-text-secondary);
}

.ap-prochart__divider {
  font-size: 12px;
  color: var(--ap-c-text-tertiary);
}

.ap-prochart__server {
  font-size: 12px;
  color: var(--ap-c-text-secondary);
}

.ap-prochart__account-id {
  font-size: 13px;
  font-weight: 600;
  color: var(--ap-c-text);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
}

/* Metric Band */
.ap-prochart__metric-band {
  display: flex;
  gap: 12px;
}

.ap-prochart__metric {
  flex: 1 1 0;
  min-width: 0;
  padding: 12px 14px;
  background: var(--ap-c-surface);
  border-radius: var(--ap-c-radius);
  border: 1px solid var(--ap-c-border);
}

.ap-prochart__metric-label {
  font-size: 11px;
  color: var(--ap-c-text-tertiary);
  line-height: 16px;
  margin-bottom: 4px;
  font-weight: 500;
}

.ap-prochart__metric-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--ap-c-text);
  line-height: 20px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ap-prochart__metric-value--primary {
  font-size: 16px;
  color: var(--ap-c-primary);
}

/* Summary Bar */
.ap-prochart__summary {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
  padding: 14px;
  background: var(--ap-c-surface);
  border-radius: var(--ap-c-radius);
  border: 1px solid var(--ap-c-border);
}

.ap-prochart__summary-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.ap-prochart__summary-label {
  font-size: 11px;
  color: var(--ap-c-text-tertiary);
  font-weight: 500;
  white-space: nowrap;
}

.ap-prochart__summary-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--ap-c-text);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ap-prochart__summary-value--up {
  color: var(--ap-c-up);
}

.ap-prochart__summary-value--down {
  color: var(--ap-c-down);
}

/* Operation Dock */
.ap-prochart__dock {
  display: flex;
  gap: 8px;
  margin-top: auto;
  padding-top: 4px;
}

.ap-prochart__btn {
  flex: 1 1 0;
  min-width: 0;
  padding: 8px 16px;
  border-radius: var(--ap-c-radius);
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  cursor: pointer;
  border: 1px solid var(--ap-c-border);
  background: var(--ap-c-bg);
  color: var(--ap-c-text);
  transition: all 0.15s ease;
  white-space: nowrap;
}

.ap-prochart__btn:hover {
  background: var(--ap-c-surface);
  border-color: var(--ap-c-text-tertiary);
}

.ap-prochart__btn--primary {
  background: var(--ap-c-primary);
  color: #fff;
  border-color: var(--ap-c-primary);
}

.ap-prochart__btn--primary:hover {
  background: var(--ap-c-primary-hover);
  border-color: var(--ap-c-primary-hover);
}

/* Chart Area */
.ap-prochart__chart-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.ap-prochart__chart-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--ap-c-text);
  margin-right: auto;
}

.ap-prochart__chart-tabs {
  display: flex;
  gap: 0;
  background: var(--ap-c-surface);
  border-radius: var(--ap-c-radius);
  border: 1px solid var(--ap-c-border);
  overflow: hidden;
}

.ap-prochart__tab {
  padding: 5px 14px;
  font-size: 12px;
  font-weight: 500;
  color: var(--ap-c-text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}

.ap-prochart__tab--active {
  background: var(--ap-c-bg);
  color: var(--ap-c-primary);
  box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.ap-prochart__period-tabs {
  display: flex;
  gap: 4px;
}

.ap-prochart__period {
  padding: 5px 12px;
  font-size: 12px;
  font-weight: 500;
  color: var(--ap-c-text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--ap-c-radius);
  cursor: pointer;
  transition: all 0.15s ease;
}

.ap-prochart__period--active {
  background: var(--ap-c-surface);
  color: var(--ap-c-text);
  border-color: var(--ap-c-border);
}

.ap-prochart__chart-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.ap-prochart__svg {
  flex: 1 1 auto;
  width: 100%;
  min-height: 120px;
}

.ap-prochart__area {
  fill: url(#ap-prochart__area);
}

.ap-prochart__line {
  fill: none;
  stroke: var(--ap-c-primary);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ap-prochart__point {
  fill: var(--ap-c-primary);
  stroke: var(--ap-c-bg);
  stroke-width: 2;
}

.ap-prochart__chart-labels {
  display: flex;
  justify-content: space-between;
  padding-top: 10px;
  font-size: 11px;
  color: var(--ap-c-text-tertiary);
  font-variant-numeric: tabular-nums;
}

/* Responsive */
@media (max-width: 720px) {
  .ap-prochart__main {
    flex-direction: column;
  }

  .ap-prochart__left {
    flex: none;
    max-width: none;
    border-right: none;
    border-bottom: 1px solid var(--ap-c-border);
    padding: 16px;
    gap: 14px;
  }

  .ap-prochart__right {
    padding: 16px;
  }

  .ap-prochart__metric-band {
    gap: 8px;
  }

  .ap-prochart__metric {
    padding: 10px 12px;
  }

  .ap-prochart__metric-value {
    font-size: 13px;
  }

  .ap-prochart__metric-value--primary {
    font-size: 14px;
  }

  .ap-prochart__summary {
    padding: 12px;
    gap: 8px 12px;
  }

  .ap-prochart__chart-header {
    margin-bottom: 12px;
  }

  .ap-prochart__svg {
    min-height: 100px;
  }
}

@media (max-width: 480px) {
  .ap-prochart__metric-band {
    flex-direction: column;
    gap: 8px;
  }

  .ap-prochart__metric {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
  }

  .ap-prochart__metric-label {
    margin-bottom: 0;
  }

  .ap-prochart__summary {
    grid-template-columns: 1fr;
  }

  .ap-prochart__dock {
    flex-direction: row;
  }

  .ap-prochart__chart-title {
    width: 100%;
    margin-bottom: 4px;
  }

  .ap-prochart__chart-header {
    gap: 8px;
  }
}

