  width: 100%;
}

.faq-section-wrapper .faq-header {
  flex: 0 0 260px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.faq-section-wrapper .faq-title {
  margin: 0 0 12px 0;
  font-size: 20px;
  font-weight: 600;
  color: var(--home-text-primary, #0f172a);
  line-height: 1.4;
}

.faq-section-wrapper .faq-desc {
  margin: 0 0 24px 0;
  font-size: 14px;
  color: var(--home-text-secondary, #64748b);
  line-height: 1.6;
}

.faq-section-wrapper .faq-link {
  font-size: 14px;
  font-weight: 500;
  color: var(--home-primary-color, var(--home-primary));
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: color 0.2s;
  margin-top: auto;
}

.faq-section-wrapper .faq-link:hover {
  color: var(--home-primary);
}

.faq-section-wrapper .faq-content {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.faq-section-wrapper .faq-item {
  border-bottom: 1px solid var(--home-border-color, var(--home-primary-faint));
}

.faq-section-wrapper .faq-item:last-child {
  border-bottom: none;
}

.faq-section-wrapper .faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
  font-size: 15px;
  font-weight: 500;
  color: var(--home-text-primary, #1e293b);
  cursor: pointer;
  list-style: none;
  transition: color 0.2s;
}

.faq-section-wrapper .faq-question::-webkit-details-marker {
  display: none;
}

.faq-section-wrapper .faq-question:hover {
  color: var(--home-primary-color, var(--home-primary));
}

.faq-section-wrapper .faq-icon {
  position: relative;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  color: var(--home-primary);
  transition: transform 0.3s ease, color 0.3s ease;
}

.faq-section-wrapper .faq-icon::before,
.faq-section-wrapper .faq-icon::after {
  content: "";
  position: absolute;
  background-color: currentColor;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  border-radius: 2px;
}

.faq-section-wrapper .faq-icon::before {
  width: 12px;
  height: 2px;
}

.faq-section-wrapper .faq-icon::after {
  width: 2px;
  height: 12px;
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.faq-section-wrapper .faq-item[open] .faq-icon {
  color: var(--home-primary-color, var(--home-primary));
}

.faq-section-wrapper .faq-item[open] .faq-icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
  opacity: 0;
}

.faq-section-wrapper .faq-answer {
  padding: 0 0 20px 0;
  font-size: 14px;
  color: var(--home-text-secondary, var(--home-primary));
  line-height: 1.6;
  animation: faqFadeIn 0.3s ease-in-out;
}

@keyframes faqFadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
