.opg-step:not(:last-child)::after {
  content: '';
  position: absolute;
  right: -12px;
  top: 16px;
  width: 24px;
  height: 2px;
  background: var(--home-border-light, var(--home-primary-faint));
}
.opg-step.completed:not(:last-child)::after {
  background: var(--home-primary-color, var(--home-primary));
}
.opg-step-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  background: var(--home-border-light, var(--home-primary-faint));
}
.opg-step.completed .opg-step-icon {
  background: var(--home-primary-color, var(--home-primary));
}
.opg-step.active .opg-step-icon {
  background: var(--home-accent-color, var(--home-primary));
  box-shadow: 0 0 0 4px var(--home-primary-faint);
}
.opg-step-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--home-text-primary, #0f172a);
}
.opg-step-status {
  font-size: 12px;
  color: var(--home-text-secondary, #64748b);
}
.opg-step.completed .opg-step-status {
  color: var(--home-primary-color, var(--home-primary));
}
.opg-step.active .opg-step-status {
  color: var(--home-accent-color, var(--home-primary));
  font-weight: 600;
}
.opg-action {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  flex-shrink: 0;
}
.opg-progress-text {
  font-size: 12px;
  color: var(--home-text-secondary, #64748b);
  font-weight: 500;
}
.opg-primary-btn {
  background: var(--home-primary-color, var(--home-primary));
  color: #fff;
  border: none;
  border-radius: var(--home-button-radius, 7px);
  padding: 8px 20px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
  white-space: nowrap;
}
.opg-primary-btn:hover {
  background: var(--home-accent-color, var(--home-primary));
}
@media (max-width: 768px) {
  .onboarding-progress-guide {
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
  }
  .opg-steps {
    flex-direction: column;
    gap: 16px;
  }
  .opg-step:not(:last-child)::after {
    display: none;
  }
  .opg-action {
    align-items: stretch;
  }
  .opg-primary-btn {
    width: 100%;
    text-align: center;
  }
}

.onboarding-guide-board {
