}

.step-status {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.2;
}

.step-status.done {
  color: var(--home-success, #16a34a);
}

.step-status.pending {
  color: var(--home-warning, #f59e0b);
}

.step-connector {
  width: 32px;
  height: 1px;
  background: var(--home-border-light, var(--home-primary-faint));
