  gap: 2px;
}

.progress-text {
  font-size: 14px;
  font-weight: 700;
  color: var(--home-text-primary, #0f172a);
}

.progress-hint {
  font-size: 12px;
  color: var(--home-text-secondary, #64748b);
}

.primary-cta {
  padding: 8px 20px;
  background: var(--home-primary, var(--home-primary));
  color: #ffffff;
  border: none;
  border-radius: var(--home-button-radius, 7px);
