.asset-overview-blue-whale {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 21px 16px 20px;
  background: var(--home-surface, #ffffff);
  border-radius: var(--home-card-radius, 12px);
  box-shadow: var(--home-card-shadow, 0 9px 18px var(--home-primary-faint));
  border: 1px solid var(--home-card-border, var(--home-primary-faint));
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  color: var(--home-text-primary, #0f172a);
  max-width: 100%;
  box-sizing: border-box;
}

.asset-overview-blue-whale__main {
  display: flex;
  align-items: flex-start;
  gap: 24px;
}

.asset-overview-blue-whale__total {
  flex: 0 0 auto;
  min-width: 200px;
}

.asset-overview-blue-whale__total-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 500;
  color: var(--home-text-secondary, #64748b);
  margin-bottom: 4px;
}

.asset-overview-blue-whale__pulse {
  display: inline-block;
  width: 8px;
  height: 8px;
