  letter-spacing: 0.3px;
}

.asset-overview-blue-whale__metric-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--home-text-primary, #0f172a);
  line-height: 1.3;
}

.asset-overview-blue-whale__metric-detail {
  font-size: 12px;
  color: var(--home-text-tertiary, var(--home-primary));
  margin-top: 2px;
}

.asset-overview-blue-whale__actions {
  display: flex;
  gap: 12px;
  margin-top: 4px;
}

.asset-overview-blue-whale__btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 16px;
  border-radius: var(--home-button-radius, 7px);
