  border-color: var(--home-primary, var(--home-primary));
}

.asset-overview-blue-whale__btn--secondary:hover {
  background: var(--home-primary, var(--home-primary));
  color: #ffffff;
}

@media (max-width: 720px) {
  .asset-overview-blue-whale__main {
    flex-direction: column;
    gap: 16px;
  }
  .asset-overview-blue-whale__total {
    min-width: 0;
    width: 100%;
  }
  .asset-overview-blue-whale__metrics {
    flex-direction: column;
    gap: 12px;
  }
  .asset-overview-blue-whale__metric {
    width: 100%;
  }
  .asset-overview-blue-whale__actions {
