.quick-actions-dock {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  font-family: inherit;
}

.dock-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 8px;
}

.dock-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 14px 8px;
  border-radius: 6px;
  background: var(--home-surface, #ffffff);
  border: 1px solid var(--home-border-light, var(--home-primary-faint));
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  text-align: center;
  min-height: 72px;
}

.dock-item:hover {
  background: var(--home-surface-soft, var(--home-primary-faint));
  border-color: var(--home-primary, var(--home-primary));
}

.dock-item--primary {
  grid-row: span 2;
  background: var(--home-primary, var(--home-primary));
  border-color: var(--home-primary, var(--home-primary));
  color: #ffffff;
  padding: 20px 12px;
  min-height: 160px;
}

.dock-item--primary:var(--home-primary);
  border-color: var(--home-accent, var(--home-primary));
}

.dock-item-icon {
  font-size: 22px;
  line-height: 1;
  margin-bottom: 6px;
  font-weight: 600;
}

.dock-item--primary .dock-item-icon {
  font-size: 28px;
  margin-bottom: 8px;
}

.dock-item-label {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  color: var(--home-text-primary, #0f172a);
}

.dock-item--primary .dock-item-label {
  font-size: 16px;
  color: #ffffff;
}

.dock-item-meta {
  font-size: 11px;
  font-weight: 400;
  line-height: 1.2;
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.8);
}

.dock-transfer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 6px;
  background: var(--home-surface, #ffffff);
  border: 1px solid var(--home-border-light, var(--home-primary-faint));
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  font-size: 13px;
  color: var(--home-text-secondary, #64748b);
}

.dock-transfer:hover {
  background: var(--home-surface-soft, var(--home-primary-faint));
  border-color: var(--home-primary, var(--home-primary));
  color: var(--home-primary, var(--home-primary));
}

.dock-transfer-icon {
  font-size: 16px;
  font-weight: 600;
}

.dock-transfer-label {
  font-weight: 600;
  color: var(--home-text-primary, #0f172a);
}

.dock-transfer-hint {
  font-size: 11px;
  color: var(--home-text-tertiary, var(--home-primary));
}

@media (max-width: 640px) {
  .dock-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto;
  }
  .dock-item--primary {
    grid-column: span 2;
    grid-row: span 1;
    min-height: 80px;
    flex-direction: row;
    gap: 8px;
    padding: 14px 16px;
  }
  .dock-item--primary .dock-item-icon {
    margin-bottom: 0;
  }
  .dock-item--primary .dock-item-meta {
    margin-top: 0;
    margin-left: auto;
  }
  .dock-transfer {
    flex-wrap: wrap;
  }
}

